# Slider Slider ## Быстрый старт Быстрый старт ```tsx
import React, { useState } from 'react';
import { Slider } from '@salutejs/sdds-finai';

export function App() {
    const [value, setValue] = useState(30);

    return (
        <div style={{ width: '25rem', display: 'flex', flexDirection: 'column' }}>
            <Slider
                min={0}
                max={100}
                value={value}
                label="Громкость"
                onChange={(val) => setValue(val)}
                onChangeCommitted={(val) => setValue(val)}
            />
        </div>
    );
}
```

## Управление внешним видом Управление внешним видом Внешний вид компонента определяется свойствами  `view`  и  `size` : ```tsx
import React, { useState } from 'react';
import { Slider } from '@salutejs/sdds-finai';

export function App() {
    const [v1, setV1] = useState(50);
    const [v2, setV2] = useState(50);
    const [v3, setV3] = useState(50);

    return (
        <div style={{ display: 'flex', gap: '1rem', flexDirection: 'column', width: '25rem' }}>
            <Slider view="default" min={0} max={100} value={v1} label="Default" onChange={setV1} />
            <Slider view="accent" min={0} max={100} value={v2} label="Accent" onChange={setV2} />
            <Slider view="gradient" min={0} max={100} value={v3} label="Gradient" onChange={setV3} />
        </div>
    );
}
```

