## Диапазон значений Диапазон значений Передайте массив из двух чисел в  `value` , чтобы использовать двойной слайдер: ```tsx
import React, { useState } from 'react';
import { Slider } from '@salutejs/sdds-finai';

export function App() {
    const [value, setValue] = useState([10, 80]);

    const sortValues = (values) =>
        values.map((val) => Math.min(100, Math.max(0, val))).sort((a, b) => a - b);

    return (
        <div style={{ width: '25rem', display: 'flex', flexDirection: 'column' }}>
            <Slider
                min={0}
                max={100}
                value={value}
                label="Цена товара"
                onChange={(values) => setValue(sortValues(values))}
                onChangeCommitted={(values) => setValue(sortValues(values))}
                onBlurTextField={(values) => setValue(sortValues(values))}
                onKeyDownTextField={(values, event) => {
                    if (event.key === 'Enter') setValue(sortValues(values));
                }}
            />
        </div>
    );
}
```

## Ориентация Ориентация Слайдер поддерживает горизонтальное (по умолчанию) и вертикальное отображение через свойство  `orientation` : ```tsx
import React, { useState } from 'react';
import { Slider } from '@salutejs/sdds-finai';

export function App() {
    const [value, setValue] = useState(30);

    return (
        <div style={{ width: '25rem', display: 'flex', flexDirection: 'column' }}>
            <Slider
                min={0}
                max={100}
                value={value}
                label="Громкость"
                orientation="horizontal"
                onChange={setValue}
            />
        </div>
    );
}
```

