## Ползунок Ползунок С помощью свойств  `pointerSize`  и  `pointerVisibility`  можно управлять размером и видимостью ползунка: ```tsx
import React, { useState } from 'react';
import { Slider } from '@salutejs/sdds-finai';

export function App() {
    const [v1, setV1] = useState(50);
    const [v2, setV2] = useState(50);
    const [v3, setV3] = useState(50);

    return (
        <div style={{ display: 'flex', gap: '1rem', flexDirection: 'column', width: '25rem' }}>
            <Slider min={0} max={100} value={v1} pointerSize="small" label="Small (по умолчанию)" onChange={setV1} />
            <Slider min={0} max={100} value={v2} pointerSize="large" label="Large" onChange={setV2} />
            <Slider min={0} max={100} value={v3} pointerSize="none" label="None (скрыт)" onChange={setV3} />
        </div>
    );
}
```

