## Шаг изменения Шаг изменения Свойство  `step`  задаёт шаг ползунка. Свойство  `multipleStepSize`  — увеличенный шаг при нажатии  `PageUp`  /  `PageDown`  (в процентах от диапазона): ```tsx
import React, { useState } from 'react';
import { Slider } from '@salutejs/sdds-finai';

export function App() {
    const [v1, setV1] = useState(50);
    const [v2, setV2] = useState(5000);

    return (
        <div style={{ display: 'flex', gap: '2rem', flexDirection: 'column', width: '25rem' }}>
            <Slider min={0} max={100} step={5} value={v1} label="Шаг 5" showScale onChange={setV1} />
            <Slider min={0} max={10000} step={500} multipleStepSize={10} value={v2} label="Шаг 500, PageUp/Down — 10%" showScale onChange={setV2} />
        </div>
    );
}
```

## Состояния Состояния Компонент поддерживает состояние  `disabled` : ```tsx
import React, { useState } from 'react';
import { Slider } from '@salutejs/sdds-finai';

export function App() {
    const [value, setValue] = useState(50);

    return (
        <div style={{ display: 'flex', gap: '1rem', flexDirection: 'column', width: '25rem' }}>
            <Slider min={0} max={100} value={value} label="Активный" onChange={setValue} />
            <Slider min={0} max={100} value={50} label="Неактивный" disabled />
        </div>
    );
}
```

## Контролируемый режим Контролируемый режим Компонент поддерживает контролируемый и неконтролируемый режимы. В контролируемом режиме передайте  `value`  и  `onChange` ; в неконтролируемом —  `defaultValue`  и  `name` : ```tsx
import React, { useState } from 'react';
import { Slider } from '@salutejs/sdds-finai';

export function App() {
    const [value, setValue] = useState(30);

    return (
        <div style={{ width: '25rem', display: 'flex', flexDirection: 'column' }}>
            <Slider
                min={0}
                max={100}
                value={value}
                label={`Текущее значение: ${value}`}
                onChange={setValue}
                onChangeCommitted={setValue}
            />
        </div>
    );
}
```

